onClick:
{{
  (async () => {
    const alertId  = Number(appsmith.store.alertId);
    const sensorId = appsmith.store.sensorId;

    // read hours from store OR fallback to the radio (in case store wasn't set)
    const hoursSel = appsmith.store.snoozeHours ?? RadioSnooze.selectedOptionValue;
    const hours    = Number(hoursSel || 0);
    const seconds  = hours * 3600;

    // strip HTML from rich text
    const note = Comment.text ? Comment.text.replace(/<[^>]*>/g,'').trim() : '';

    if (!alertId || !sensorId) { showAlert("Missing alert selection", "error"); return; }
    if (!hours) { showAlert("Pick a snooze period", "warning"); return; }
    if (note.length < 3) { showAlert("Please enter a brief comment", "warning"); return; }

    await ACK_API.run({ alertId });
    await SNOOZE_API.run({ sensorId, seconds, alertId });
    await COMMENT_API.run({ alertId, text: `[SNOOZE ${hours}h] ${note}` });

    await getOpenAlerts.run();
    closeModal('ModalComment');
    closeModal('ModalPeriod');
    resetWidget('Comment', true);
    storeValue('snoozeHours', undefined);
    storeValue('alertId', undefined);
    storeValue('sensorId', undefined);
    showAlert('😴 Snoozed & noted', 'success');
  })().catch(e => showAlert('Snooze failed: ' + (e.message || e), 'error'))
}}
